#include <setjmp.h>

extern jmp_buf host_fake_loop_escape;
extern int host_fake_loop_armed;
void host_fake_break_loop(void);

/* Call a function that may never return. It comes back here either way:
 *
 *     vTaskDelay_fake.abort_after = 3;
 *     HOST_RUN_BOUNDED(heartbeat_scheduler_task(NULL));
 *     TEST_ASSERT_EQUAL_INT(3, connectivity_service_publish_fake.calls);
 *
 * BOTH LINES ARE REQUIRED. `abort_after` alone counts the calls but has
 * nowhere to unwind to, so the loop keeps running: it is HOST_RUN_BOUNDED
 * that installs the landing point. Setting one without the other is the
 * single commonest way to hang a test binary, and it is reported as an
 * IGNORE naming this exact mistake rather than as a timeout.
 *
 * A function that returns normally is unaffected, so this is always safe.
 */
#define HOST_RUN_BOUNDED(call)                        \
    do {                                              \
        host_fake_loop_armed = 1;                      \
        if (setjmp(host_fake_loop_escape) == 0) {      \
            call;                                      \
        }                                              \
        host_fake_loop_armed = 0;                      \
    } while (0)

